    private User getOrCreateSeller(String fullName, String email, String university, String campus, String phone) {
        return userRepository.findByEmailIgnoreCase(email)
                .orElseGet(() -> {
                    User u = new User();
                    u.setFullName(fullName);
                    u.setEmail(email.toLowerCase().trim());
                    u.setPassword(passwordEncoder.encode("password123"));
                    u.setUniversity(university);
                    u.setCampus(campus);
                    u.setPhone(phone);
                    u.setRole(Role.STUDENT);
                    u.setEnabled(true);
                    return userRepository.save(u);
                });
    }

    private void createDemoListing(Long academicBookId, User seller, String title, String author, String publisher,
                                   String edition, String isbn, String courseCode, String category, String campus,
                                   BigDecimal price, Condition condition, String imageUrl, String defectNotes,
                                   String description, boolean isPromoted, String paymentRef) {

        Optional<AcademicBook> bookOpt = academicBookRepository.findById(academicBookId);
        if (bookOpt.isEmpty()) {
            return;
        }
        AcademicBook book = bookOpt.get();

        // Idempotent check: if this demo seller already posted this academic book, update or skip
        Optional<Product> existing = productRepository.findAll().stream()
                .filter(p -> p.getAcademicBook() != null && p.getAcademicBook().getId().equals(academicBookId)
                        && p.getSeller() != null && p.getSeller().getId().equals(seller.getId()))
                .findFirst();

        Product product;
        if (existing.isPresent()) {
            product = existing.get();
        } else {
            product = new Product();
            product.setAcademicBook(book);
            product.setSeller(seller);
        }

        product.setTitle(title);
        product.setAuthor(author);
        product.setPublisher(publisher);
        product.setEdition(edition);
        product.setIsbn(isbn);
        product.setCourseCode(courseCode);
        product.setCategory(category);
        product.setCampus(campus);
        product.setPrice(price);
        product.setCondition(condition);
        product.setImageUrl(imageUrl);
        product.setDefectNotes(defectNotes);
        product.setDescription(description);
        product.setStatus(ListingStatus.AVAILABLE);
        product.setPromoted(isPromoted);
        if (isPromoted) {
            product.setPromotedUntil(LocalDateTime.now().plusDays(7));
        }
        product = productRepository.save(product);

        // Ensure PromotionPayment
        final Product finalProduct = product;
        if (paymentRepository.findTopByProductIdOrderByCreatedAtDesc(finalProduct.getId()).isEmpty()) {
            PromotionPayment payment = new PromotionPayment();
            payment.setSeller(seller);
            payment.setProduct(finalProduct);
            payment.setFeeAmount(new BigDecimal("15000.00"));
            payment.setDurationDays(7);
            payment.setTransactionReference(paymentRef);

            if (isPromoted) {
                payment.setStatus(PromotionPaymentStatus.PAID);
                payment.setPaymentMethod("ADMIN_DEMO_WAIVER");
                payment.setAdminNote("DEMO_ADMIN_WAIVER: Phê duyệt hiển thị mẫu cho môi trường phát triển (Demo Seed)");
                payment.setPaymentNotes("Phí đăng bài mẫu phục vụ kiểm thử môi trường phát triển");
                payment.setVerifiedAt(LocalDateTime.now());
                userRepository.findByEmailIgnoreCase("admin@bookloop.edu").ifPresent(payment::setVerifiedBy);
            } else {
                payment.setStatus(PromotionPaymentStatus.PENDING);
                payment.setPaymentMethod("BANK_TRANSFER");
                payment.setPaymentNotes("Chờ thanh toán phí quảng cáo");
            }
            paymentRepository.save(payment);
        }
    }
